import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Get the watermark timestamp
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events up to and including the watermark
    cdc_events = cdc_events[cdc_events["event_ts"] <= high_ts].copy()

    # If no events to apply, return the snapshot as-is
    if cdc_events.empty:
        return {"new_snapshot": target_snapshot}

    # Create a working copy of the snapshot indexed by item_id
    snapshot_dict = {}
    for _, row in target_snapshot.iterrows():
        snapshot_dict[row["item_id"]] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Sort events by (event_ts, event_seq) for sequential application
    cdc_events = cdc_events.sort_values(by=["event_ts", "event_seq"]).reset_index(drop=True)

    # Apply events sequentially per item
    for _, event in cdc_events.iterrows():
        item_id = event["item_id"]
        op = event["op"]
        qty = event["qty"]
        event_ts = event["event_ts"]

        if op == "R":  # Receipt: add to quantity
            # If item doesn't exist or was deleted, start from 0
            if item_id not in snapshot_dict:
                snapshot_dict[item_id] = {"qty_on_hand": 0.0, "last_event_ts": event_ts}
            snapshot_dict[item_id]["qty_on_hand"] += qty
            snapshot_dict[item_id]["last_event_ts"] = event_ts

        elif op == "A":  # Adjustment: set absolute quantity
            # Create or update item with absolute value
            snapshot_dict[item_id] = {"qty_on_hand": qty, "last_event_ts": event_ts}

        elif op == "D":  # Delete: remove item from snapshot
            # Mark as deleted by removing from dict
            if item_id in snapshot_dict:
                del snapshot_dict[item_id]

    # Reconstruct the snapshot DataFrame
    if snapshot_dict:
        rows = []
        for item_id, data in snapshot_dict.items():
            rows.append({
                "item_id": item_id,
                "qty_on_hand": data["qty_on_hand"],
                "last_event_ts": data["last_event_ts"]
            })
        new_snapshot = pd.DataFrame(rows)
        # Ensure correct dtypes
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"])
    else:
        # All items deleted
        new_snapshot = pd.DataFrame(
            columns=["item_id", "qty_on_hand", "last_event_ts"]
        )
        new_snapshot = new_snapshot.astype({
            "item_id": "int64",
            "qty_on_hand": "float64",
            "last_event_ts": "datetime64[us]"
        })

    return {"new_snapshot": new_snapshot}
